import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Targets and tiers","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Targets and tiers | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/targets"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/targets"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/targets"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/targets"}]]},"headers":[],"relativePath":"xclang/reference/targets.md","filePath":"en/xclang/reference/targets.md","lastUpdated":1791227177000}'),o={name:"xclang/reference/targets.md"};function s(n,t,i,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="targets-and-tiers" tabindex="-1">Targets and tiers <a class="header-anchor" href="#targets-and-tiers" aria-label="Permalink to &quot;Targets and tiers&quot;">​</a></h1><h2 id="hosts" tabindex="-1">Hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to &quot;Hosts&quot;">​</a></h2><p>A host is a machine the toolchain runs on. Each has its own archive, and every archive carries every target.</p><table tabindex="0"><thead><tr><th>host</th><th>archive built on</th><th>tested on</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux x64</td><td>ubuntu-24.04</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux x64, cross-compiled</td><td>ubuntu-24.04-arm</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td>Linux x64, cross-compiled; the toolchain is a MinGW program</td><td>windows-2025</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td>Linux x64, cross-compiled</td><td>windows-11-arm</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS arm64</td><td>macos-15</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td>macOS arm64, cross-compiled</td><td>macos-15-intel</td></tr></tbody></table><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>also spelled</th><th>C runtime</th><th>runs on</th><th>builds on</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-pc-linux-gnu</code>, <code>x86_64-linux-gnu</code> (Bazel)</td><td>glibc 2.17</td><td>glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-pc-linux-gnu</code>, <code>aarch64-linux-gnu</code> (Bazel)</td><td>glibc 2.17</td><td>glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code>, <code>x86_64-pc-windows-gnu</code></td><td>mingw-w64 with UCRT</td><td>Windows 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code>, <code>aarch64-pc-windows-gnu</code></td><td>mingw-w64 with UCRT</td><td>Windows 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>arm64-apple-darwin</code>, <code>arm64-apple-macos</code>, <code>aarch64-apple-macosx</code>, ...</td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>macOS hosts</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td><code>x86_64-apple-macos</code>, <code>x86_64-apple-macosx</code></td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>macOS hosts</td></tr></tbody></table><p>All six are tier 1. The macOS targets build on macOS hosts only, because they need Apple&#39;s SDK, which comes from Xcode there; macOS from any host, with the SDK fetched from Apple by the user, is <a href="./../design/roadmap">in research</a>.</p><p>What each target has:</p><table tabindex="0"><thead><tr><th></th><th>Linux</th><th>Windows</th><th>macOS</th></tr></thead><tbody><tr><td>libc++, libc++abi</td><td>static</td><td>static</td><td>static (not the system&#39;s <code>libc++.dylib</code>)</td></tr><tr><td>unwinder</td><td>libunwind, static</td><td>libunwind, static</td><td>the system&#39;s (libSystem)</td></tr><tr><td>compiler-rt builtins, profile</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>ASan, TSan, LSan, UBSan, libFuzzer</td><td>yes</td><td>no</td><td>yes</td></tr><tr><td>libc++&#39;s ASan build</td><td>yes</td><td>no</td><td>yes</td></tr><tr><td>linker</td><td>ld.lld</td><td>ld.lld (MinGW driver)</td><td>ld64.lld; <code>-fuse-ld=ld</code> for Apple&#39;s</td></tr></tbody></table><h2 id="tiers" tabindex="-1">Tiers <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;Tiers&quot;">​</a></h2><p>Each target has a tier, as Rust&#39;s targets do. The tier says how a target is tested, and so how much a release promises about it.</p><ul><li><strong>Tier 1</strong>: built for every release, and its tests run on a GitHub-hosted runner of the target itself (for future targets: Windows x64 runs x86 programs, wasmtime WebAssembly ones); a failure stops the release.</li><li><strong>Tier 2</strong>: built for every release, and its tests run under emulation or virtualization: qemu, a virtual machine, Android&#39;s emulator, Apple&#39;s simulators.</li><li><strong>Tier 3</strong>: built, or buildable on demand; programs are compiled and linked for it, not run.</li></ul><p>A target marked <strong>SDK</strong> needs a vendor SDK that the user fetches and accepts the license of; xclang&#39;s tests fetch it the same way.</p><p>What &quot;its tests run on the target itself&quot; means for today&#39;s six:</p><ul><li>tests/smoke.ts builds C and C++ programs for every target on every host, and runs those the machine can run (its own target; x86_64 macOS programs on arm64 macOS through Rosetta; x86_64 Windows programs on Windows on Arm).</li><li>bazel.yml builds tests/bazel on every host for every other target it builds for, 22 host-to-target pairs, and runs the tests on a machine of the target: Linux-built Windows programs on Windows, Windows-built Linux programs on Linux, and so on. No emulator is involved.</li><li>examples.yml runs the quick start on every host.</li></ul><p>The targets planned and considered, with their tiers, are in the <a href="./../design/roadmap#targets">roadmap</a>.</p>',16)])])}const g=e(o,[["render",s]]);export{m as __pageData,g as default};
